#nullable enable // autogenerated

using System.Collections.Generic;
using MVZ2.GameContent.Damages;
using MVZ2.GameContent.Detections;
using MVZ2.Vanilla.Detections;
using MVZ2.Vanilla.Entities;
using MVZ2.Vanilla.Properties;
using MVZ2Logic.Entities;
using PVZEngine.Buffs;
using PVZEngine.Callbacks;
using PVZEngine.Collisions;
using PVZEngine.Damages;
using PVZEngine.Definitions;
using PVZEngine.Entities;

namespace MVZ2.GameContent.Buffs.Contraptions
{
    [AutoBuffDefinition(VanillaBuffNames.Contraption.onbashiraFall)]
    public class OnbashiraFallBuff : BuffDefinition
    {
        public OnbashiraFallBuff(string nsp, string name) : base(nsp, name)
        {
            AddTrigger(LevelCallbacks.POST_ENTITY_COLLISION, PostEntityCollisionCallback);
            AddTrigger(LevelCallbacks.POST_ENTITY_CONTACT_GROUND, PostEntityContactGroundCallback, priority: 1);
        }
        private void PostEntityCollisionCallback(LevelCallbacks.PostEntityCollisionParams args, CallbackResult result)
        {
            var state = args.state;
            if (state != EntityCollisionHelper.STATE_ENTER)
                return;
            var collision = args.collision;
            var contraption = collision.Entity;
            var other = collision.Other;
            if (!CanSmash(contraption, other))
                return;
            var buffs = contraption.GetBuffs<OnbashiraFallBuff>();
            if (buffs.Length <= 0)
                return;
            float damageMultiplier = 0;
            foreach (var buff in buffs)
            {
                damageMultiplier += GetDamageMultiplier(buff);
            }
            if (damageMultiplier <= 0)
                return;
            var damage = contraption.GetDamage() * damageMultiplier;
            collision.OtherCollider.TakeDamage(damage, new DamageEffectList(VanillaDamageEffects.IMPACT, VanillaDamageEffects.MUTE, VanillaDamageEffects.DAMAGE_BODY_AFTER_ARMOR_BROKEN), contraption);
        }
        private void PostEntityContactGroundCallback(LevelCallbacks.PostEntityContactGroundParams args, CallbackResult result)
        {
            var contraption = args.entity;

            var buffs = contraption.GetBuffs<OnbashiraFallBuff>();
            if (buffs.Length <= 0)
                return;
            float damageMultiplier = 0;
            foreach (var buff in buffs)
            {
                damageMultiplier += GetDamageMultiplier(buff);
            }
            var damage = contraption.GetDamage() * damageMultiplier;

            smashBuffer.Clear();
            smashDetector.DetectMultiple(contraption, smashBuffer);
            foreach (var target in smashBuffer)
            {
                var other = target.Entity;
                if (!CanSmash(contraption, other))
                    continue;
                target.TakeDamage(damage, new DamageEffectList(VanillaDamageEffects.IMPACT, VanillaDamageEffects.MUTE, VanillaDamageEffects.DAMAGE_BOTH_ARMOR_AND_BODY), contraption);
            }

            contraption.DestroyConflictGridEntities();
            contraption.RemoveBuffs(buffs);
        }
        public static bool CanSmash(Entity contraption, Entity other)
        {
            return other != contraption && other.IsVulnerableEntity() && contraption.IsHostile(other);
        }
        public static float GetDamageMultiplier(Buff buff) => buff.GetProperty<float>(PROP_DAMAGE_MULTIPLIER);
        public static void SetDamageMultiplier(Buff buff, float value) => buff.SetProperty(PROP_DAMAGE_MULTIPLIER, value);
        public static readonly VanillaBuffPropertyMeta<float> PROP_DAMAGE_MULTIPLIER = new VanillaBuffPropertyMeta<float>("damage_multiplier", 18);
        private List<IEntityCollider> smashBuffer = new List<IEntityCollider>();
        private Detector smashDetector = new CollisionDetector(true);
    }
}
